-- ---------------------------------------------------------------------
-- Step 0 — has the column already been added?
-- EXPECTED: zero rows before, one row after.
-- ---------------------------------------------------------------------
SELECT column_name, data_type
FROM   workspace.information_schema.columns
WHERE  table_schema = 'dq_triage'
  AND  table_name = 'dq_config_rule_registry'
  AND  column_name = 'join_sql';

-- ---------------------------------------------------------------------
-- Step 1 — add the column. Existing rows read NULL, which is correct for
-- every single-table rule and is what the runner reads as 'this cross-table
-- rule has no join and cannot be executed'.
-- ---------------------------------------------------------------------
ALTER TABLE workspace.dq_triage.dq_config_rule_registry
  ADD COLUMN join_sql STRING COMMENT 'For a cross-table rule: the FROM-clause body the check runner reads instead of target_table -- the joined table expression with its aliases and ON condition. NOT a full SELECT: rule_expr stays the predicate and references these aliases, so the predicate is stored once. NULL for every single-table rule.';

