FROM   workspace.dq_triage.dq_config_rule_registry
WHERE  rule_id = 'XREF_NAME_AGREEMENT'
  AND  rule_version = (SELECT max(rule_version) FROM workspace.dq_triage.dq_config_rule_registry
                       WHERE rule_id = 'XREF_NAME_AGREEMENT');

